plist.dict:
Label
com.gastown.daemon

ProgramArguments

    {{xml .GTPath}}
    daemon
    run


WorkingDirectory
{{xml .TownRoot}}

RunAtLoad


{{- if .ExitTimeOutSeconds }}
ExitTimeOut
{{.ExitTimeOutSeconds}}
{{- end }}

KeepAlive

    Crashed

    SuccessfulExit



StandardOutPath
{{xml .TownRoot}}/daemon/daemon.log

StandardErrorPath
{{xml .TownRoot}}/daemon/daemon.log

EnvironmentVariables

    GT_TOWN_ROOT
    {{xml .TownRoot}}
    {{- range $key, $value := .Env }}
    {{xml $key}}
    {{xml $value}}
    {{- end }}


ProcessType
Standard
